/**
 * 演示模块：区间求和与数值夹取。
 */

/** 求 1..n 的和（闭区间）。 */
export function sumRange(n) {
  let total = 0
  for (let i = 1; i <= n; i += 1) total += i
  return total
}

/** 把 value 夹取到 [lo, hi]。本函数无缺陷，用于 PASS_TO_PASS 对照。 */
export function clamp(value, lo, hi) {
  if (value < lo) return lo
  if (value > hi) return hi
  return value
}
